function fundingSliderPanel(s){const ctx=modellingContext();return `<details class="source-options" open><summary>Adjust the funding sources</summary><p class="fine">Set the maximum from each account. For investments, the slider caps gross sale proceeds; tax is reserved from those proceeds. Ron fills the balance from the other permitted sources.</p>${ctx.sources.map(x=>`<label class="funding-slider" for="source-${x.id}"><span>${esc(x.name)}<b id="cap-${x.id}">${money(plan.sourceCaps?.[x.id]??x.balance)}</b></span><input type="range" id="source-${x.id}" data-source-cap="${x.id}" min="0" max="${x.balance}" step="100" value="${plan.sourceCaps?.[x.id]??x.balance}"><small>${x.kind==='sale'?'Gross sale ceiling':'Cash ceiling'} · ${x.owner==='personal'?'Personal':'Company'}</small></label>`).join('')}<label class="check-line"><input id="flow-cross" type="checkbox" ${plan.cross?'checked':''}> Allow documented shareholder loan transfers</label><label class="check-line"><input id="flow-sales" type="checkbox" ${plan.sales?'checked':''}> Allow fund sales</label></details>`}
function forecastMarkup(s,p){const f=s.forecast||forecastRoute(s,p,modellingContext()),price=Number(p.offerPrice),qty=price?p.amount/price:null;return `<div class="forecast-result"><h3>Now and later</h3>${p.type==='startup'?'<div class="offer-facts"><p>Company valuation: '+(p.valuation?money(p.valuation):'unknown')+' · '+esc(p.valuationBasis||'basis unknown')+'. Previous reference: '+(p.previousValuation?money(p.previousValuation):'unknown')+'.</p><p>Terms: '+esc(p.terms||'unknown')+'. '+(p.terms==='preferred'?'Preference rights and dilution are not priced by this simple growth scenario. Adviser review required.':'Share class and eligibility need verification.')+'</p></div>':''}<p class="fine">${f.years.toFixed(1)} years · ${f.growth}% annual price growth · ${f.yield}% annual cash yield · ${p.policy==='income'?'distributions paid':'net distributions reinvested'}. Assumptions, not predictions.</p>${qty?`<div class="plain-row"><span>Initial shares / units at ${unitValue(price)}</span><strong>${qty.toLocaleString('en-GB',{maximumFractionDigits:3})}</strong></div><div class="plain-row"><span>Scenario future price per share</span><strong>${unitValue(f.futurePrice)}</strong></div>`:'<p class="fine">Share price unknown. Quantity and share-class checks are open for your Partner.</p>'}<div class="forecast-tax-grid">${[['Sale tax to fund it',s.now],['Income tax while held',f.incomeTax],['Disposal tax',f.disposalTax],['Personal extraction tax',f.extractionTax]].map(([n,v])=>`<div><span>${n}</span><strong class="tax-number">${money(v)}</strong></div>`).join('')}</div><div class="plain-row"><span>Scenario value after modelled taxes<small>Includes income received; company proceeds may remain in the company if selected.</small></span><strong class="positive">${money(f.netValue)}</strong></div>${s.eis?`<p class="intelligent-note">Potential EIS Income Tax relief up to ${money(s.eis)}, subject to liability and eligibility. Not subtracted from this comparison.</p>`:''}${!AU&&Number(p.incomeYield)>0?'<p class="warning-note">Check distribution classification and the assumed personal rate. Savings rates change to 22%/42%/47% from 6 April 2027. This scenario uses your entered effective rate; it does not calculate marginal tax bands.</p>':''}<details><summary>What the forecast includes</summary><p class="fine">Annual price growth, cash income, tax on income, reinvestment cost basis, disposal gains and a sample withdrawal route. No future CGT annual exemption is assumed. UK EIS disposal relief is used only when explicitly selected as a hypothetical and the modelled holding period is at least three years. ${AU?'Personal CGT discount is conditional on a sufficient holding period; company gains have no discount. Fully franked cash dividends are grossed up with a limited credit.':'UK eligible ISA income/gains are sheltered. Corporate ordinary-dividend exemption must be selected and verified; fund/interest income is otherwise modelled as taxable.'}</p><p class="fine">Company withdrawals use the entered remaining loan principal first, then a dividend scenario. Lawful distributable reserves, franking credits, actual personal tax bands, losses, other income, fees, dilution, preference waterfalls and foreign taxes require professional review. A supplied effective personal rate is a scenario input, not a full tax computation. No pension/super withdrawal or ESIC concession is calculated.</p></details></div>`}
const scenarioBeforeForecast=scenarioMarkup;scenarioMarkup=function(s,p){let html=scenarioBeforeForecast(s,p);if(!s.legs)return html;html=html.replace(/<div class="plan-tax-strip">[\s\S]*?<\/div>(?=<p|<details)/,forecastMarkup(s,p));if(!html.includes('forecast-result'))html=forecastMarkup(s,p)+html;if(AU){html=html.replace(/<p class="fine">Company and personal stakes[\s\S]*?<\/p>/,'<p class="fine">ESIC company and investor eligibility needs a separate assessment. No offset or special CGT concession is assumed.</p>').replace(/<p class="warning-note">A short holding period[\s\S]*?<\/p>/,'<p class="warning-note">Startup shares may be illiquid. ESIC and disposal treatment require professional assessment.</p>');html=html.replace(/<details class="model-assumptions">[\s\S]*?<\/details>/,'<p class="fine">Australian resident scenario. 30% company tax; source fund disposals assume long-held personal assets and a 47% effective marginal rate including Medicare. ESIC incentives, trusts and super investing need a separate professional assessment. <a href="#rules">Rules & coverage →</a></p>').replace(/£1m|EIS|ISA/g,x=>x==='EIS'?'ESIC review':x==='ISA'?'personal account':x)}return html};
