{id:'ct600',date:'2027-03-31',who:companyLabel,name:'Corporation Tax return',period:'Year ended 31 March 2026',note:'Example CT600 deadline, separate from the 1 January 2027 tax payment date. Instalment rules need review.',figures:[['Draft tax creditor','£14,500'],['Submission status','Not submitted']],questions:[['outside','Any income, disposals or expenses missing from the company records?'],['paid','Any additional company tax payments or refunds?']],type:'accounts'}
