function filingState(id){return state.filingAnswers[id]||(state.filingAnswers[id]={answers:{},details:{},stage:'Questions to answer',version:1,numbers:false,complete:false,evidence:false,notes:''})}
function filingOverview(){return `${sectionNav('filing','filing')}<h1>Filing</h1><p>Answer what’s missing. Confirm the numbers. Get on with your day.</p>${filingGroups.map(g=>{const f=filingState(g.id),left=g.questions.filter(([id])=>!f.answers[id]).length;return `<a class="filing-batch" href="#checklist/${g.id}"><span class="batch-date">${g.date?when(g.date):'Date to confirm'}</span><h2>${g.who}</h2><span>${g.name} · ${g.period}</span><div><strong>${f.stage}</strong><small>${left} unanswered question${left===1?'':'s'} →</small></div></a>`}).join('')}<p class="fine">Illustrative deadlines, not a filing service. Evidence, identifiers, professional checks and actual agent arrangements must be confirmed.</p>`}
function checklistPage(g){const f=filingState(g.id),requiresEvidence=['accounts','personal','ct600'].includes(g.id),unknown=g.questions.some(([id])=>!f.answers[id]||f.answers[id]==='unsure'||(f.answers[id]==='yes'&&!f.details[id])),canReview=!unknown&&f.complete&&f.numbers&&(!requiresEvidence||f.evidence);return `${backButton('filing')}<p class="eyebrow">${g.date?when(g.date):'Submission date to confirm'} · ${g.who}</p><h1>${g.name}</h1><p>${g.period}</p><p class="fine">${g.note} <a href="${AU?(g.id==='confirmation'?'https://www.asic.gov.au/for-business-and-companies/companies/company-annual-review':'https://www.ato.gov.au/individuals-and-families/your-tax-return/how-to-lodge-your-tax-return'):g.id==='personal'?'https://www.gov.uk/self-assessment-tax-returns/deadlines':'https://www.gov.uk/prepare-file-annual-accounts-for-limited-company'}" target="_blank" rel="noopener">Official deadlines ↗</a></p><div class="checklist-stage">${f.stage} · version ${f.version}</div><section><h2>What we already have</h2>${g.figures.map(([a,b])=>`<div class="plain-row"><span>${a}</span><strong>${b}</strong></div>`).join('')}<p class="fine">Pre-filled illustrative figures. Report corrections below; extra payments are not automatically credited until reconciled.</p></section><form id="filing-questions" data-checklist="${g.id}"><h2>A few things to check</h2>${g.questions.map(([id,q],i)=>`<fieldset class="filing-question"><legend><span>${i+1}.</span> ${q}</legend><div class="answer-options">${[['no','No'],['yes','Yes'],['unsure','I’m not sure']].map(([v,l])=>`<label><input type="radio" name="q-${id}" value="${v}" ${f.answers[id]===v?'checked':''}> ${l}</label>`).join('')}</div><div class="answer-detail" ${['yes','unsure'].includes(f.answers[id])?'':'hidden'}><label for="detail-${id}" class="fine">${id==='valuation'?'A new valuation alone is not assumed to create a tax event. Give the date, basis and share class if known.':'If yes or unsure, tell your accountant what changed. For tax payments, include the amount, date and reference.'}</label><textarea id="detail-${id}" rows="2" placeholder="Only if there’s something to add…">${esc(f.details[id]||'')}</textarea></div></fieldset>`).join('')}<label for="filing-correction">Anything to correct in the figures?</label><textarea id="filing-correction" rows="2">${esc(f.notes||'')}</textarea><label class="check-line"><input id="filing-numbers" type="checkbox" ${f.numbers?'checked':''}> These pre-filled figures match what I know, apart from corrections above.</label><label class="check-line"><input id="filing-complete" type="checkbox" ${f.complete?'checked':''}> I have disclosed anything relevant outside ron.</label>${requiresEvidence?`<p class="fine">Supporting statements and loan/credit reconciliations are needed. Actual uploaded files remain unanalysed in this demo.</p><label class="check-line"><input id="filing-evidence" type="checkbox" ${f.evidence?'checked':''}> Simulate the required supporting evidence being reconciled.</label>`:''}<button class="primary wide">Save answers for accountant review →</button></form><section class="draft-links"><h2>Want the details?</h2><a class="text-link" href="#filingdraft/${g.id}">Read or edit the full draft →</a></section>${f.stage==='Awaiting accountant review'?`<section class="demo-review"><h2>Accountant review · demo</h2><p>${canReview&&!f.notes?'The sample answers and evidence are complete.':'Open questions, corrections or evidence still need resolving.'}</p><button class="secondary" data-accountant-clear="${g.id}" ${canReview&&!f.notes?'':'disabled'}>Mark professional checks complete (demo)</button><p class="fine">This does not verify actual evidence or statutory eligibility. Corrections require a revised draft and reconciled final numbers.</p></section>`:''}${f.stage==='Ready for your approval'?`<section><h2>Ready to approve</h2><p>Your accountant’s example review is complete. The same final figures above are presented for confirmation.</p><label class="check-line"><input id="filing-authorise" type="checkbox"> I approve this sample version for the demo.</label><button class="primary wide" data-filing-approve="${g.id}" disabled>Approve for filing (demo) →</button></section>`:''}${f.stage==='Approved · demo'?'<p class="intelligent-note">Approved in this browser. Nothing has been signed or submitted to a tax authority. A real submission needs verified identifiers, agent authority and a receipt.</p>':''}`}
function auReport(g){return `<div class="report-page"><div class="report-running">${esc(g.who)}<span>ron.</span></div><span class="report-draft">ILLUSTRATIVE AUSTRALIAN REVIEW PACK · NOT FOR LODGMENT</span><h1>${g.name}</h1><p>${g.period}</p>${reportTable(g.figures)}<h2>Source records and reconciliation</h2><p>Amounts are illustrative review figures, not a completed ATO form or a statutory financial report. TFN, ABN/ACN, tax-agent authority and the applicable lodgment program are not verified.</p><h2>Investment classifications</h2><p>Separate interest, dividends and franking credits, trust/fund statements and capital gains. Eligible personal CGT discounts do not apply to company gains. Passive-investment company example: 30%, not an assumed 25% base-rate-entity rate.</p><h2>Shareholder loans</h2><p>Genuine principal owed by the company is financing, not a deductible expense. Private payments or loans in the opposite direction need Division 7A review.</p><h2>Client questions</h2>${g.questions.map(([,q])=>'<p>'+q+'</p>').join('')}<h2>Review and approval</h2><p>Evidence, final figures, agent due dates, professional review and client authorisation must be completed. No ATO or ASIC lodgment is created by this example.</p></div>`}
function cleanDraft(html){const t=document.createElement('template');t.innerHTML=html;const allowed=new Set(['DIV','SPAN','P','BR','H1','H2','H3','TABLE','THEAD','TBODY','TR','TD','TH','UL','OL','LI','STRONG','EM','B','SMALL']);for(const n of [...t.content.querySelectorAll('*')]){if(['SCRIPT','STYLE','IFRAME','OBJECT','INPUT','BUTTON'].includes(n.tagName)){n.remove();continue}if(!allowed.has(n.tagName)){n.replaceWith(document.createTextNode(n.textContent));continue}for(const a of [...n.attributes])if(!['class','colspan','rowspan'].includes(a.name))n.removeAttribute(a.name)}return t.innerHTML}
function filingDraft(g){const html=state.filingDrafts[g.id]||(AU?auReport(g):g.type==='personal'?personalReturn():g.type==='confirmation'?confirmationStatement():companyAccounts());return `${backButton('checklist/'+g.id)}<h1>Full draft</h1><p class="fine">Editable sample working document. Saving changes invalidates earlier reviews and approvals. This is not filing-ready content.</p><div class="draft-edit-toolbar"><button class="primary" data-save-full-draft="${g.id}">Save draft changes</button><span>Version ${filingState(g.id).version} · local only</span></div><div id="editable-filing" class="report-stack" contenteditable="true" role="textbox" aria-label="Editable full draft" aria-multiline="true">${html.replaceAll('Will Hackett','Alex Morgan')}</div>`}
reviewRows=function(){return filingGroups.slice(0,3).map(g=>`<a class="task-row" href="#checklist/${g.id}"><div><strong>${g.name}</strong><span>${g.who} · ${g.date?when(g.date):'Date to confirm'} · ${filingState(g.id).stage}</span></div><span>→</span></a>`).join('')};
window.ronScreens.filing=window.ronScreens.review=filingOverview;
fullFiling=function(type){navigate('checklist/'+(filingGroups.some(g=>g.id===type)?type:'accounts'))};
window.ronScreens.files=function(){return `${sectionNav('filing','files')}<h1>Files</h1><p>One place for investment documents, agreements and tax records.</p>${dropZone()}<section><h2>Received documents</h2>${state.docs.map(d=>`<button class="task-row" data-document="${d.id}"><div><strong>${esc(d.name)}</strong><span>${esc(d.kind)} · human review pending</span></div><span>→</span></button>`).join('')||'<p class="muted">No documents received in this example.</p>'}</section><section><h2>Prepared drafts</h2>${filingGroups.map(g=>`<a class="task-row" href="#filingdraft/${g.id}"><div><strong>${g.name}</strong><span>${g.who} · ${g.period}</span></div><span>→</span></a>`).join('')}</section>`};
const sampleClients=[{id:'alex',name:'Alex Morgan',company:companyLabel,wealth:3950000,summary:'Founder exit · personal + company',phone:AU?'+61 4XX XXX XXX':'+44 7XXX XXX XXX',last:'Call · 12 October: keep two years of spending accessible.'},{id:'sam',name:'Sam Chen',company:AU?'Chen Investments Pty Ltd':'Chen Investments Ltd',wealth:6200000,summary:'Business owner · income + growth',phone:AU?'+61 4XX XXX XXX':'+44 7XXX XXX XXX',last:'Meeting · 9 October: considering a business investment.'},{id:'jordan',name:'Jordan Ellis',company:'Personal portfolio',wealth:9400000,summary:'Executive · employee shares + retirement',phone:AU?'+61 4XX XXX XXX':'+44 7XXX XXX XXX',last:'Call · 7 October: employee-share documents requested.'}];
function selectedClient(){return sampleClients.find(c=>c.id===state.adviserClient)||sampleClients[0]}
function contactPanel(){const c=selectedClient();return `<aside class="client-notes"><div class="contact-card"><span class="eyebrow">Client contact · fictional</span><h2>${c.name}</h2><span>${c.phone}</span><button class="secondary wide" id="call-client">Call client ↗</button><small>Placeholder number · calls disabled</small></div><h3>Interaction history</h3><p class="interaction-note">${c.last}</p>${state.adviserNotes.filter(n=>n.client===c.id).map(n=>`<p class="interaction-note"><small>${when(n.date)}</small>${esc(n.text)}</p>`).join('')}<form id="adviser-note-form"><label for="adviser-note">Add a note</label><textarea id="adviser-note" rows="5" required placeholder="What did you agree? What happens next?"></textarea><button class="primary wide">Save note</button></form><p class="fine">Local demo notes. No customer contact or external record is created.</p></aside>`}
function adviserHome(){return `<div class="adviser-heading"><div><p class="eyebrow">Adviser workspace · ${regionName}</p><h1>Your clients</h1><p>Plans to review. Questions to answer. The context beside you.</p></div><a class="text-link" href="#tour">Feature tour →</a></div><div class="adviser-summary"><span><strong>3</strong> sample clients</span><span><strong>${state.requests.filter(r=>r.stage==='Planned').length}</strong> investment requests</span><span><strong>${filingGroups.length}</strong> filing checklists</span></div><div class="client-directory">${sampleClients.map(c=>`<a href="#client/${c.id}"><div><strong>${c.name}</strong><span>${c.summary}</span></div><b>${money(c.wealth)}</b><small>${c.id==='alex'?'Investment plan to review':'Example client record'}</small><span>→</span></a>`).join('')}</div><section class="adviser-explainer"><h2>How a small firm could serve more clients</h2><ol><li>Documents arrive in one inbox. AI proposes classifications, extracted fields and follow-up questions.</li><li>The client tests an investment idea. The adviser gets the source records, scenarios and open questions together.</li><li>The adviser reviews the plan, calls the client and records the discussion alongside it.</li><li>The client signs the approved version. Connected execution follows the authorised sequence.</li><li>Accountants prepare filings. Clients answer only what is missing and confirm final figures.</li></ol><p class="fine">Proposed product workflow. Document AI, live integrations, DocuSign and submissions are simulated here. The demo does not claim proven capacity savings.</p></section>`}
function clientPage(id){state.adviserClient=id;const c=selectedClient(),r=state.requests.find(r=>r.stage==='Planned')||state.requests.find(r=>r.stage),panel=state.adviserPanel;return `${backButton('adviser')}<div class="adviser-layout"><article><p class="eyebrow">${c.summary}</p><h1>${c.name}</h1><div class="client-wealth">${money(c.id==='alex'?totalWealth():c.wealth)}<small>Combined illustrative net wealth</small></div><div class="client-tabs">${[['overview','Portfolio'],['plans','Plans'],['files','Documents'],['filing','Filing']].map(([k,v])=>`<button data-client-panel="${k}" aria-pressed="${panel===k}">${v}</button>`).join('')}</div>${panel==='overview'?`<h2>What matters to this client</h2><div class="plain-row"><span>Objective</span><strong>Long-term growth</strong></div><div class="plain-row"><span>Spending reserve</span><strong>${money(45000)}</strong></div><div class="plain-row"><span>Primary home</span><strong>Excluded from investment funding</strong></div><h2>Portfolio</h2>${c.id==='alex'?ledger.positions.filter(p=>p.owner==='household'||p.owner==='fic'&&!p.company).map(p=>`<div class="portfolio-line"><span>${esc(p.name)}<small>${esc(owners[p.owner])} · ${p.qty.toLocaleString('en-GB')} units</small></span><strong>${money(value(p))}</strong></div>`).join(''):'<p>Additional sample client: connect holdings and verify ownership during onboarding.</p>'}<p class="fine">Company shares and underlying positions are shown as records; the consolidated wealth total counts economic value once.</p>`:panel==='plans'?`<h2>Client investment requests</h2>${r?`<a class="request-callout" href="#plan/${r.id}"><span>“I’d like to invest ${money(r.amount)}. Can you check the plan?”</span><strong>${esc(r.name)}</strong><small>${r.stage} · review sources, terms, tax and future cash →</small></a>`:'<p>No requests.</p>'}<p>Open the plan to approve or reject it, record your reasoning and keep the client’s contact details alongside the work.</p>`:panel==='files'?`<h2>Document processing</h2><div class="processing-track"><span>Received</span><span>Classified</span><span>Fields proposed</span><span>Professional check</span></div><div class="sample-extraction"><h3>${AU?'Startup offer & ESIC evidence':'Startup offer & EIS evidence'} · sample</h3><div class="plain-row"><span>Detected price per share</span><strong>${money(10)}</strong></div><div class="plain-row"><span>Share class</span><strong>Preference rights · needs review</strong></div><div class="plain-row"><span>Missing question</span><strong>Is the valuation pre- or post-money?</strong></div><p class="fine">Illustrative extraction output. No AI has read an actual document in this prototype. Account records are not changed until approved.</p></div><a class="text-link" href="#files">Open document inbox →</a>`:`<h2>Upcoming submissions</h2>${reviewRows()}`}</article>${contactPanel()}</div>`}
function adviserTasks(){return `<h1>Work queue</h1><p>Review the exceptions with the client context already attached.</p><h2>Plans</h2>${planRows()}<h2>Filing questions</h2>${reviewRows()}<h2>Documents</h2><a class="task-row" href="#client/alex"><div><strong>Offer terms need checking</strong><span>Alex Morgan · share class, price and valuation basis</span></div><span>→</span></a>`}
window.ronScreens.adviser=adviserHome;window.ronScreens.workqueue=adviserTasks;
const tourStages=[{title:'The client sees their position',copy:'One combined wealth figure, available cash, tax dates and actions. The home is counted in wealth but is never suggested as investment funding.',route:'wealth',role:false},{title:'They test an investment',copy:'Compare personal, company and split ownership. Change the assumptions and source limits; see immediate sale tax, income, disposal, extraction and holdings impact.',route:'invest/funding',role:false},{title:'The adviser gets the context',copy:'The portfolio, requests, contact details and previous conversations are together. AI proposes document fields; the professional checks them.',route:'client/alex',role:true},{title:'Approve, sign, then execute',copy:'A versioned plan needs Partner approval and a client signature. Steps run in dependency order; a failed step stops later instructions. Everything here is simulated.',route:'execution',role:true},{title:'Filing becomes a checklist',copy:'A submission date, a person or company, the missing questions and final figures. Full drafts remain available to read or edit.',route:'checklist/personal',role:false},{title:'Rules have dates and sources',copy:'Each jurisdiction uses its own rules. Enacted future changes are flagged; incomplete tax modules and unverified inputs are explicit.',route:'rules',role:true}];
function tourHome(){return `<div class="tour-intro"><p class="eyebrow">A startup proposal · adviser demonstration</p><h1>More control for clients.<br>More time for your firm.</h1><p>A proposed platform for private investors and investment companies, delivered through firms with wealth advice and tax accountancy in-house.</p><p>Clients make plans. Your team reviews them. The platform could handle document processing, authorised execution and filing preparation around those decisions.</p><div class="tour-region"><a href="?region=uk#tour" ${!AU?'aria-current="page"':''}>United Kingdom</a><a href="?region=au#tour" ${AU?'aria-current="page"':''}>Australia</a></div><button class="primary wide" id="start-tour">Start the ${AU?'Australian':'UK'} feature tour →</button><div class="tour-choices"><a href="#adviser" data-role="adviser">Explore adviser workspace →</a><a href="#wealth" data-role="client">Explore client view →</a><a href="/${region}/">Read the startup proposal →</a></div><p class="fine">About 5 minutes. Fictional clients, records and forecasts. No bank/broker API, AI document analysis, DocuSign or tax submission is connected. Rules were checked against official sources on 17 October 2026; this is a curated demonstration, not comprehensive tax software.</p></div>`}
function tourBanner(){if(state.tourStep===null)return '';const t=tourStages[state.tourStep];return `<div class="tour-banner"><div><span>ADVISER TOUR · ${state.tourStep+1} / ${tourStages.length}</span><h2>${t.title}</h2><p>${t.copy}</p></div><div class="tour-actions">${state.tourStep?'<button class="text-link" id="tour-prev">← Previous</button>':''}<button class="primary" id="tour-next">${state.tourStep===tourStages.length-1?'Finish':'Next →'}</button><button class="text-link" id="tour-end">End tour</button></div></div>`}
function goTourStep(n){if(n>=tourStages.length){state.tourStep=null;persist();navigate('tour');return}state.tourStep=n;const t=tourStages[n];state.adviserMode=t.role;if(n===1){plan={type:'startup',eis:AU?'unknown':'yes',name:'Example Robotics',amount:200000,date:'2026-10-26',years:'5',cross:true,sales:true,route:'auto',cadence:'once',policy:'reinvest',offerPrice:10,valuation:10000000,valuationBasis:'post',previousValuation:8000000,terms:'preferred',annualGrowth:10,incomeYield:0,incomeRate:AU?47:35.75,receipt:'taxable',exitTarget:'personal'};}if(n===2)state.adviserPanel='plans';let route=t.route;if(route==='execution'){const r=state.requests.find(r=>r.stage==='Ready to execute')||state.requests.find(r=>r.stage);route='plan/'+r.id}persist();navigate(route)}
window.ronScreens.tour=tourHome;
const dynamicBeforeAdviser=window.ronDynamic;window.ronDynamic=function(v){if(v.startsWith('checklist/')){const g=filingGroups.find(g=>g.id===v.split('/')[1]);return g?checklistPage(g):'<h1>Checklist not found</h1>'}if(v.startsWith('filingdraft/')){const g=filingGroups.find(g=>g.id===v.split('/')[1]);return g?filingDraft(g):'<h1>Draft not found</h1>'}if(v.startsWith('client/'))return clientPage(v.split('/')[1]);return dynamicBeforeAdviser(v)};
const bindWizardBeforeAdviser=bindWizard;bindWizard=function(){bindWizardBeforeAdviser();const step=view().split('/')[1];if(step==='amount'&&$('#flow-amount'))$('#flow-amount').onsubmit=e=>{e.preventDefault();plan.amount=Number($('#flow-sum').value);plan.name=$('#flow-name')?.value.trim()||plan.name||'';if($('#flow-name')&&!plan.name)return;navigate('invest/terms')};if($('#terms-form'))$('#terms-form').onsubmit=e=>{e.preventDefault();plan.offerPrice=$('#offer-price').value?Number($('#offer-price').value):null;plan.valuation=$('#company-valuation')?.value?Number($('#company-valuation').value):null;plan.previousValuation=$('#previous-valuation')?.value?Number($('#previous-valuation').value):null;plan.valuationBasis=document.querySelector('input[name="valuation-basis"]:checked')?.value||'unknown';plan.terms=document.querySelector('input[name="share-terms"]:checked')?.value||'unknown';plan.rights=$('#rights-note')?.value||'';navigate('invest/date')};if(step==='horizon'){document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{plan.years=b.dataset.choice;plan.disposal='';navigate(['fund','help'].includes(plan.type)?'invest/policy':'invest/assumptions')});$('#flow-date').onsubmit=e=>{e.preventDefault();const d=$('#flow-disposal').value;if(!d){$('#flow-disposal').required=true;$('#flow-disposal').reportValidity();return}plan.disposal=d;plan.years=String(Math.max(.1,(new Date(d)-new Date(plan.date))/31557600000));navigate(['fund','help'].includes(plan.type)?'invest/policy':'invest/assumptions')}}if(step==='policy')document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{plan.policy=b.dataset.choice;navigate('invest/assumptions')});if($('#forecast-form'))$('#forecast-form').onsubmit=e=>{e.preventDefault();Object.assign(plan,{annualGrowth:Number($('#annual-growth').value),incomeYield:Number($('#income-yield').value),incomeRate:Number($('#personal-income-rate').value),loanAtExit:Number($('#loan-at-exit').value),receipt:document.querySelector('input[name="receipt-type"]:checked').value,exitTarget:document.querySelector('input[name="exit-target"]:checked').value,assumeEIS:!!$('#assume-eis')?.checked});navigate('invest/funding')};document.querySelectorAll('[data-source-cap]').forEach(input=>input.oninput=e=>{plan.sourceCaps=plan.sourceCaps||{};plan.sourceCaps[e.target.dataset.sourceCap]=Number(e.target.value);const routes=compareRoutes(plan),s=chooseScenario(routes,plan);$('#cap-'+e.target.dataset.sourceCap).textContent=money(Number(e.target.value));$('#funding-options').innerHTML=fundingOptions(s,routes);$('#funding-projection').innerHTML=fundingProjection(s);sessionStorage.setItem('ron-investment-draft-'+region,JSON.stringify(plan));bind()})};
const bindBeforeAdviser=bind;
bind=function(){bindBeforeAdviser();if($('#start-tour'))$('#start-tour').onclick=()=>goTourStep(0);if($('#tour-prev'))$('#tour-prev').onclick=()=>goTourStep(state.tourStep-1);if($('#tour-next'))$('#tour-next').onclick=()=>goTourStep(state.tourStep+1);if($('#tour-end'))$('#tour-end').onclick=()=>{state.tourStep=null;persist();render()};document.querySelectorAll('[data-role]').forEach(a=>a.onclick=()=>{state.adviserMode=a.dataset.role==='adviser';persist()});document.querySelectorAll('[data-client-panel]').forEach(b=>b.onclick=()=>{state.adviserPanel=b.dataset.clientPanel;persist();render()});if($('#call-client'))$('#call-client').onclick=()=>note('Demo contact only. A live product would open the client’s verified phone number.');if($('#adviser-note-form'))$('#adviser-note-form').onsubmit=e=>{e.preventDefault();const text=$('#adviser-note').value.trim();if(!text)return;state.adviserNotes.push({client:selectedClient().id,date:today,text});persist();render()};
 if($('#filing-questions'))$('#filing-questions').onsubmit=e=>{e.preventDefault();const id=e.target.dataset.checklist,g=filingGroups.find(g=>g.id===id),f=filingState(id);for(const [key] of g.questions){f.answers[key]=document.querySelector('input[name="q-'+key+'"]:checked')?.value||'';f.details[key]=$('#detail-'+key).value.trim()}f.notes=$('#filing-correction').value.trim();f.numbers=$('#filing-numbers').checked;f.complete=$('#filing-complete').checked;f.evidence=!!$('#filing-evidence')?.checked;f.stage='Awaiting accountant review';f.version++;persist();render();note('Answers saved locally. Accountant review remains required.')};document.querySelectorAll('[data-accountant-clear]').forEach(b=>b.onclick=()=>{const f=filingState(b.dataset.accountantClear);f.stage='Ready for your approval';f.reviewVersion=f.version;persist();render()});if($('#filing-authorise'))$('#filing-authorise').onchange=e=>document.querySelector('[data-filing-approve]').disabled=!e.target.checked;document.querySelectorAll('[data-filing-approve]').forEach(b=>b.onclick=()=>{const f=filingState(b.dataset.filingApprove);if(!$('#filing-authorise').checked||f.reviewVersion!==f.version)return;f.stage='Approved · demo';persist();render()});document.querySelectorAll('[data-save-full-draft]').forEach(b=>b.onclick=()=>{const id=b.dataset.saveFullDraft,f=filingState(id);state.filingDrafts[id]=cleanDraft($('#editable-filing').innerHTML);f.stage='Questions to answer';f.version++;f.reviewVersion=null;f.numbers=false;f.complete=false;f.notes='Edited draft needs professional reconciliation with the summary figures.';persist();navigate('checklist/'+id);note('Draft saved. Prior approvals invalidated; final figures need reconciliation.')});
};
function regionaliseScreen(){const root=$('#screen');const walk=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;const nodes=[];while(node=walk.nextNode())nodes.push(node);for(const n of nodes)n.nodeValue=n.nodeValue.replaceAll('Will Hackett','Alex Morgan').replaceAll('2LR Investments Ltd',companyLabel).replaceAll('2LR Property Ltd',AU?'2LR Property Pty Ltd':'2LR Property Ltd').replaceAll('£',AU?'AU$':'£');}
const renderBeforeAdviser=render;render=function(){renderBeforeAdviser();const v=view(),root=$('#screen');if(['adviser','workqueue'].includes(v)||v.startsWith('client/'))state.adviserMode=true;if(state.adviserMode&&v.startsWith('plan/')){root.innerHTML='<div class="adviser-layout"><article>'+root.innerHTML+'</article>'+contactPanel()+'</div>';root.classList.add('adviser-wide')}else root.classList.toggle('adviser-wide',['adviser','workqueue'].includes(v)||v.startsWith('client/'));if(state.tourStep!==null&&v!=='tour')root.insertAdjacentHTML('afterbegin',tourBanner());const links=state.adviserMode?[['adviser','Clients'],['workqueue','Work queue'],['rules','Rules']]:[['wealth','Wealth'],['cashflow','Cashflow'],['filing','Filing']];$('header nav').innerHTML=links.map(([id,label])=>`<a href="#${id}" ${v===id?'aria-current="page"':''}>${label}</a>`).join('');$('header .tools').innerHTML=`<a class="mode-switch" href="#${state.adviserMode?'wealth':'adviser'}" data-role="${state.adviserMode?'client':'adviser'}">${state.adviserMode?'Client view':'Adviser view'}</a><a class="region-chip" href="?region=${AU?'uk':'au'}#tour">${AU?'AU':'UK'} ↔</a><button class="plain" id="demo-theme" aria-label="Switch colour theme">◐</button>`;$('#demo-theme').onclick=()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';localStorage.setItem('ron-appearance',document.documentElement.dataset.theme);render()};if(AU){$('footer>a').setAttribute('href','/au/');$('footer>a').textContent='Australian proposal ↗';$('footer>span').textContent='Australian resident example · 17 October 2026';}regionaliseScreen();bind();};
render();
const renderFinalRegional=render;render=function(){renderFinalRegional();if(AU){const travel=$('#screen section:last-child');if(view()==='cashflow'&&travel?.textContent.includes('UK nights'))travel.innerHTML='<h2>Travel & residency</h2><p>Forward itineraries into the proposed document inbox. Your adviser checks residence, departure CGT and continuing Australian obligations.</p><p class="fine">Travel days alone do not determine residency. No departure date or tax exemption is inferred by this demo.</p><button class="text-link" data-event="review">Review the planned move →</button>';bind()}};
const resetForAdviser=$('#reset-simple').onclick;$('#reset-simple').onclick=()=>{resetForAdviser();location.reload()};render();
const adviserFinalBind=bind;bind=function(){adviserFinalBind();const form=$('#filing-questions');if(form)form.oninput=e=>{if(e.target.type==='radio'){const d=e.target.closest('fieldset')?.querySelector('.answer-detail');if(d)d.hidden=e.target.value==='no'}const f=filingState(form.dataset.checklist);if(['Ready for your approval','Approved · demo'].includes(f.stage)){f.stage='Questions to answer';f.reviewVersion=null;f.version++;persist();document.querySelector('[data-filing-approve]')?.setAttribute('disabled','');const stage=$('.checklist-stage');if(stage)stage.textContent='Answers changed · new accountant review required';}}};
const adviserPublishedRender=render;render=function(){adviserPublishedRender();const a=$('footer>a');if(a){a.href='/'+region+'/';a.textContent='Startup proposal ↗'}if(AU){const all=$('#screen');const walk=document.createTreeWalker(all,NodeFilter.SHOW_TEXT);let n;while(n=walk.nextNode()){if(n.parentElement?.closest('.model-assumptions'))continue;n.nodeValue=n.nodeValue.replaceAll('Buy chosen ISA fund','Buy chosen personal fund')}}bind()};render();
if(AU){const intakeBeforeRegion=quickIntake;quickIntake=function(file){if(!file)return;intakeBeforeRegion(file);const d=state.docs.at(-1);d.kind=/esic/i.test(file.name)?'Innovation-company evidence':/emi|eis|isa/i.test(file.name)?'Foreign-scheme document · adviser to classify':/super/i.test(file.name)?'Superannuation document':d.kind;persist();render()}}
const finalWizardBind=bindWizard;bindWizard=function(){finalWizardBind();if(view()==='invest/type')document.querySelectorAll('[data-choice]').forEach(b=>{const next=b.onclick;b.onclick=()=>{const startup=b.dataset.choice==='startup';plan.annualGrowth=startup?10:5;plan.incomeYield=startup?0:2.5;plan.offerPrice=null;plan.valuation=null;plan.previousValuation=null;plan.terms='unknown';next()}})};
if(!location.hash)history.replaceState(null,'','#tour');render();
